\begin{axis}[axis lines=middle,xlabel=$x$,ylabel=$y$,xmin=0.05,xmax=8,ymin=-6,ymax=12,samples=200]
\addplot[thick,domain=0.05:8] {3*x+(-3)+2*ln(x)/x};
\addplot[dashed,domain=0.05:8] {3*x+(-3)};
\end{axis}
